function Counter() {
  const [count, setCount] = useState(0);
  const handleClick = () => {
    setCount(count + 1);
    console.log(count);
  };
  return <button onClick={handleClick}>+{count}</button>;
}

function Timer() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => {
      console.log(count);
    }, 1000);
    return () => clearInterval(id);
  }, []); // empty dependency array
  return <button onClick={() => setCount(c => c + 1)}>Add</button>;
}

